// No inputs or outputs; this function only prints current (r|e)uid/(r|e)gid.
// Preconditions: stdout available; does not require privileges.
// Invoke target function.
EUID_PRINT();

// Validation summary: Safe to call in fuzzer; no persistent state or external symbols required.
// Side effect is printing to stdout, which is acceptable for coverage and does not affect object pool.

// __gcov_flush has no inputs and no return value. It is safe to call with no preconditions.
// On GCC >= 11.1 with HAVE_GCOV, this will call __gcov_dump() and __gcov_reset().
// Otherwise, it may be a no-op macro or provided by the gcov runtime.
// We also track invocation count in the global fuzzer state for potential cross-stub reasoning.
int flush_calls = FUZZ_GET_ATTR_INT_GLOBAL("gcov_flush_calls");
FUZZ_SET_ATTR_INT_GLOBAL("gcov_flush_calls", flush_calls + 1);

// Invoke the target function
__gcov_flush();

// No outputs to return; nothing else to validate since API has no error reporting.

// __gcov_dump has no inputs and no return value. It is safe to call with no preconditions.
// When HAVE_GCOV is not defined, this symbol may be a no-op macro; emitting the call remains valid.
int dump_calls = FUZZ_GET_ATTR_INT_GLOBAL("gcov_dump_calls");
FUZZ_SET_ATTR_INT_GLOBAL("gcov_dump_calls", dump_calls + 1);

// Invoke the target function
__gcov_dump();

// No outputs; API exposes no error channel to assert.

// __gcov_reset has no inputs and no return value. It is safe to call with no preconditions.
// When HAVE_GCOV is not defined, this may be a no-op macro; the call is still valid after macro expansion.
int reset_calls = FUZZ_GET_ATTR_INT_GLOBAL("gcov_reset_calls");
FUZZ_SET_ATTR_INT_GLOBAL("gcov_reset_calls", reset_calls + 1);

// Invoke the target function
__gcov_reset();

